Schema for **update_app**:
```json
{
  "name": "update_app",
  "description": "Update an application's metadata. Requires the id from list_apps.",
  "input_schema": {
    "type": "object",
    "properties": {
      "app_id": {
        "type": "string",
        "description": "Application id (Mongo _id)"
      },
      "name": {
        "type": "string",
        "description": "New display name"
      },
      "properties": {
        "type": "object",
        "description": "Properties to merge into the app"
      },
      "languages": {
        "type": "array",
        "description": "Supported languages"
      },
      "default_language": {
        "type": "string",
        "description": "Default language code"
      },
      "version": {
        "type": "integer",
        "description": "Expected version (optimistic lock)"
      },
      "message": {
        "type": "string",
        "description": "Commit message",
        "default": "Updated via CFA"
      }
    },
    "required": [
      "app_id"
    ]
  }
}
```
